def comps(cells):
    cells=set(map(tuple,cells)); seen=set(); out=[]
    for c in list(cells):
        if c in seen: continue
        stack=[c]; comp=[]
        while stack:
            x=stack.pop()
            if x in seen: continue
            seen.add(x); comp.append(x)
            r,cc=x
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    if (dr,dc)!=(0,0) and (r+dr,cc+dc) in cells: stack.append((r+dr,cc+dc))
        out.append(comp)
    return out
