import numpy as np
def transform(g):
    g=[row[:] for row in g]; a=np.array(g)
    bg=a[0,0]
    # find object rows: rows containing object color
    rows=np.where((a!=bg).any(axis=1))[0]
    # split into two vertical bands
    splits=np.where(np.diff(rows)>1)[0]
    r1=rows[:splits[0]+1]; r2=rows[splits[0]+1:]
    A=a[r1.min():r1.max()+1]!=bg
    B=a[r2.min():r2.max()+1]!=bg
    h=max(A.shape[0],B.shape[0]); w=max(A.shape[1],B.shape[1])
    out=[row[:] for row in g]
    def pad(M):
        P=np.zeros((h,w),bool); P[:M.shape[0],:M.shape[1]]=M; return P
    PA,PB=pad(A),pad(B)
    # cells beyond other's bbox columns
    for P,Q,(rbase,cca,ccb) in [(PA,PB,(r1.min(),A.shape[1],B.shape[1])),
                                 (PB,PA,(r2.min(),B.shape[1],A.shape[1]))]:
        if cca>ccb:  # P wider: copy P's cells in cols>=ccb to Q's band
            for r in range(P.shape[0]):
                for c in range(cca,w):
                    if P[r,c]:
                        rr,cc=rbase+r, ccb+c
                        if 0<=rr<len(out) and 0<=cc<len(out[0]) and out[rr][cc]==bg:
                            out[rr][cc]=1
    return out
