def transform(g, dbg=False):
    g=[row[:] for row in g]; a=np.array(g)
    bg=a[0,0]
    rows=np.where((a!=bg).any(axis=1))[0]
    splits=np.where(np.diff(rows)>1)[0]
    r1=rows[:splits[0]+1]; r2=rows[splits[0]+1:]
    bands=[]
    for rr in (r1,r2):
        sub=a[rr.min():rr.max()+1]
        cols=np.where((sub!=bg).any(axis=0))[0]
        bands.append((int(rr.min()), sub, int(cols.min()), int(cols.max())))
    out=[row[:] for row in g]
